(baseDir, targetDir) => {
    var baseFiles = Directory.GetFiles(baseDir, "*.png");
    var pairs = new List<ImagePair>();
    foreach (var b in baseFiles)
    {
        var bName = Path.GetFileName(b);
        var tName = bName.Replace("_before", "_after");
        var tFile = Path.Combine(targetDir, tName);
        if (File.Exists(tFile))
        {
            pairs.Add(new ImagePair
            {
                BaseImagePath = b,
                TargetImagePath = tFile,
                PairName = Path.GetFileNameWithoutExtension(bName)
            });
        }
    }
    return pairs;
}

(baseDir, targetDir) => {
    var baseFiles = Directory.GetFiles(baseDir, "*.png");
    var targetFiles = Directory.GetFiles(targetDir, "*.png");
    var targetMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
    foreach (var tf in targetFiles)
    {
        var clean = Regex.Replace(Path.GetFileName(tf), @"^\d{8}_", "");
        targetMap[clean] = tf;
    }
    var pairs = new List<ImagePair>();
    foreach (var bf in baseFiles)
    {
        var clean = Regex.Replace(Path.GetFileName(bf), @"^\d{8}_", "");
        if (targetMap.TryGetValue(clean, out var tf))
        {
            pairs.Add(new ImagePair
            {
                BaseImagePath = bf,
                TargetImagePath = tf,
                PairName = Path.GetFileNameWithoutExtension(clean)
            });
        }
    }
    return pairs;
}

(baseDir, targetDir) => {
    string[] exts = { "*.png", "*.jpg", "*.jpeg", "*.bmp" };
    var bFiles = exts.SelectMany(e => Directory.GetFiles(baseDir, e)).ToList();
    var tFiles = exts.SelectMany(e => Directory.GetFiles(targetDir, e)).ToList();
    var tMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
    foreach (var tf in tFiles)
    {
        var name = Path.GetFileNameWithoutExtension(tf);
        if (!tMap.ContainsKey(name)) tMap[name] = tf;
    }
    var pairs = new List<ImagePair>();
    foreach (var bf in bFiles)
    {
        var name = Path.GetFileNameWithoutExtension(bf);
        if (tMap.TryGetValue(name, out var tf))
        {
            pairs.Add(new ImagePair
            {
                BaseImagePath = bf,
                TargetImagePath = tf,
                PairName = name
            });
        }
    }
    return pairs;
}
